<?php
require __DIR__ . '/vendor/autoload.php';

use App\Domain\Utils\Web3SignatureVerifier;

// Known valid Ethereum personal_sign test vector
// Message: "hello world"
// Address: 0x9858EfFD232B4033E47d90003D41EC34EcaEdA94
// Signature generated by ethers.js wallet.signMessage("hello world")
$address   = '0x9858effd232b4033e47d90003d41ec34ecaeda94';
$message   = 'hello world';
$signature = '0xd4b4d291beefd7cd9e0de1a6e8a2c9f4a3d0b9b3c2beb62d7e4de76b9d2e2e34fe32c51a74b37b4c4f3abff1e543e6f7f4efb6dc4b745c7e37e3a85c7d0f8781b';

echo "Testing known signature vector...\n";
$result = Web3SignatureVerifier::verify($address, $message, $signature);
echo "Result: " . ($result ? "VERIFIED ✓" : "FAILED ✗") . "\n\n";

// Test with invalid sig
echo "Testing invalid signature...\n";
$bad = Web3SignatureVerifier::verify($address, $message, '0x' . str_repeat('ab', 65));
echo "Result: " . (!$bad ? "Correctly rejected ✓" : "BUG - accepted invalid ✗") . "\n";
